function distinctPeople(keySets: string[][]): number {
  const parent = keySets.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const owner = new Map<string, number>();
  keySets.forEach((keys, i) => {
